local function CHD_Cmd(...)
  if type(funcLuaMenuCommand) == "function" then
    return pcall(funcLuaMenuCommand, ...)
  end
  return false
end

local function CHD_Get(...)
  local ok, v = CHD_Cmd(...)
  if ok then
    return v
  end
  return nil
end

local function CHD_Lc(...)
  if type(funcLuaCommand) == "function" then
    local ok, v = pcall(funcLuaCommand, ...)
    if ok then
      return v
    end
  end
  return nil
end

local function CHD_Log(msg)
  CHD_Lc(CHD.LOG, "EVT dock_panel " .. msg)
end

local function CHD_Pack(...)
  return {n = select("#", ...), ...}
end

local function CHD_PanelOn()
  return EVT_CHD_PANEL == true and EVT_UI_PRESET ~= "off"
end

-- BetterUI 1.21.9 (owner 2026-10-13): the TÁCTICAS block (title + the 3 tactic plates) stays as in the original game:
-- no tactics row, no slices / scissor, no tactics focus re-routing; the rest of the panel layout is unchanged.
local function CHD_TacOn()
  return CHD_PanelOn() and EVT_CHD_TACTICS == true
end

local function CHD_ClipOn()
  return CHD_TacOn() and EVT_CHD_CLIP == true
end

local function CHD_ArrowsOn()
  return EVT_CHD_ARROWS == true and EVT_UI_PRESET ~= "off"
end

local function CHD_AtdfOn()
  return CHD_PanelOn() and EVT_CHD_ATDF == true
end

-- the AT / DF layer's transform as recorded (absolute: sending it again changes nothing)
local function CHD_AtdfSend()
  local st = CHD.atdf
  CHD_Cmd(CHD.LAYER_SCALE, CHD_ATDF.layer, st.s, st.s, 1, 0)
  CHD_Cmd(CHD.LAYER_POS, CHD_ATDF.layer, st.x, st.y, 0, 0)
end

-- ---- layout ------------------------------------------------------------------------------------------------------------
local CHD_ATC_TACTICS = 727258178   -- _atc_tactics01: the frame locator of the TÁCTICAS block

local function CHD_Place(layer, idx, rows, skip)
  for _, r in ipairs(rows) do
    if r[1] ~= skip then
      CHD_Cmd(CHD.NODE_POS, layer, idx, r[1], 0, r[2])
      CHD_Cmd(CHD.NODE_POS, layer, idx, r[1], 1, r[3])
      if r[4] ~= nil then
        CHD_Cmd(CHD.NODE_SCALE, layer, idx, r[1], r[4], r[5])
      end
    end
  end
end

local function CHD_HideCmdText(idx)
  CHD_Cmd(CHD.SET_TEXT, CHD.CMD, CHD.TEXT_CMD, "", idx)
  CHD_Cmd(CHD.NODE_VIS, CHD.CMD, CHD.TEXT_CMD, false, idx)
end

local function CHD_HideConfText()
  CHD_Cmd(CHD.TEXT_VIS, CHD.CONF, CHD.TEXT_BUILD, false, 0)
  CHD_Cmd(CHD.NODE_VIS, CHD.CONF, CHD.TEXT_BUILD, false, 0)
end

-- the kit's frame locator (absolute frame units), as placed last
local function CHD_KitAtc(frame)
  if CHD.kit[frame] == nil then
    for _, r in ipairs(CHD_FRAME[frame]) do
      if r[1] == CHD.ATC_UNI then
        CHD.kit[frame] = {r[2], r[3]}
      end
    end
  end
  return CHD.kit[frame]
end

-- the header layers in a mode: "header" = crest | team name | kit | player plate | «Nv.»; "panel" = retail header,
-- the kit as the retail EQUIPACIÓN box under the panel
local function CHD_ApplyHeader(layer, mode)
  local hdr = mode == "header"
  if layer == CHD.UNI then
    if hdr then
      CHD_Place(layer, 0, CHD_UNI)
      CHD_Cmd(CHD.SET_PRIO, layer, 0, CHD.KIT_PRIO)
    else
      CHD_Place(layer, 0, CHD_UNI_RETAIL)
    end
    for _, n in ipairs(CHD_UNI_HIDE) do
      CHD_Cmd(CHD.NODE_VIS, layer, n, not hdr, 0)
    end
    CHD_Cmd(CHD.MESH_VIS, layer, CHD.KIT_SHADOW, not hdr, 0)
  elseif layer == CHD.BAR then
    if hdr then
      CHD_Place(layer, 0, CHD_BAR)
      CHD_Cmd(CHD.SWAP, layer, CHD_HDR.nv_atlas, CHD_HDR.nv_sprite, CHD_HDR.nv_slot, 0, 0)
      -- round 8: the white card «Nv.» in the level digits' blue, fully opaque
      local c = CHD_HDR.nv_rgb
      CHD_Cmd(CHD.PRIM_COLOR, layer, 0, CHD_HDR.nv_mesh, c[1], c[2], c[3])
      CHD_Cmd(CHD.PRIM_ALPHA, layer, 0, CHD_HDR.nv_mesh, 1)
    else
      CHD_Place(layer, 0, CHD_BAR_RETAIL)
      CHD_Cmd(CHD.SWAP, layer, CHD_HDR_CHECK.nv_atlas, CHD_HDR.nv_slot, CHD_HDR.nv_slot, 0, 0)
      CHD_Cmd(CHD.PRIM_COLOR, layer, 0, CHD_HDR.nv_mesh, 1, 1, 1)   -- the retail label carries its own blue
    end
  elseif layer == CHD.NAME then
    CHD_Place(layer, 0, hdr and CHD_NAME or CHD_NAME_RETAIL)
  end
end

-- every node edit of one layer instance (absolute values: applying it again changes nothing)
local function CHD_Apply(layer, idx)
  idx = idx or 0
  if CHD_PanelOn() then
    if CHD_FRAME[layer] ~= nil then
      if idx == 0 then
        CHD_Place(layer, 0, CHD_FRAME[layer], (not CHD_TacOn()) and CHD_ATC_TACTICS or nil)
        local k = CHD.hdr == "header" and CHD_KitAtc(layer) or CHD_UNI_PANEL[layer]
        if k ~= nil then
          CHD_Cmd(CHD.NODE_POS, layer, 0, CHD.ATC_UNI, 0, k[1])
          CHD_Cmd(CHD.NODE_POS, layer, 0, CHD.ATC_UNI, 1, k[2])
        end
      end
    elseif layer == CHD.BASE then
      if CHD_TacOn() then
        CHD_Place(layer, 0, CHD_BASE)
      end
    elseif layer == CHD.CMD then
      if not CHD_TacOn() then
        return
      end
      if idx <= 2 then
        CHD_Place(layer, idx, CHD_ClipOn() and CHD_CMD_CLIP[idx] or CHD_CMD_BOX)
        CHD_HideCmdText(idx)
        if not CHD_ClipOn() and CHD_Lc(CHD.SLICES_READY) == true then
          CHD_Cmd(CHD.SWAP, layer, CHD.SLICE_ATLAS, CHD.SLICES[idx], CHD.PLATE_SLOT, 0, idx)
        end
      end
    elseif layer == CHD.TAC then
      if idx <= 2 and CHD_TacOn() then
        CHD_Place(layer, idx, CHD_FOCUS)
      end
    elseif layer == CHD.FORM then
      CHD_Place(layer, 0, CHD_FORM)
    elseif layer == CHD.CONF then
      CHD_Place(layer, 0, CHD_CONF)
      CHD_HideConfText()
    elseif (layer == CHD.UNI or layer == CHD.BAR or layer == CHD.NAME) and CHD.hdr ~= nil then
      CHD_ApplyHeader(layer, CHD.hdr)
    end
  end
  if layer == CHD_ATDF.layer and (CHD.atdf.x ~= 0 or CHD.atdf.y ~= 0 or CHD.atdf.s ~= 1) then
    CHD_AtdfSend()                -- keep the engine on the recorded transform (Step corrects it from there)
  end
  if layer == CHD.DOCKNO and CHD_ArrowsOn() then
    CHD_Place(layer, 0, CHD_DOCKNO)
  end
  if not CHD.logged and (CHD_PanelOn() or CHD_ArrowsOn()) then
    CHD.logged = true
    CHD_Log("on (panel " .. tostring(CHD_PanelOn()) .. ", clip " .. tostring(CHD_ClipOn()) .. ", arrows "
      .. tostring(CHD_ArrowsOn()) .. ")")
  end
end

-- every Step: each box's plate clipped to its box (the box's frame layer recomputes its rectangle first: the dock's
-- slide-in / dock switch move them)
local CHD_G
local function CHD_Clip()
  for i = 0, 2 do
    if CHD_Get(CHD.IS_OPEN, CHD.CMD, i) == true and CHD_Get(CHD.IS_OPEN, CHD.TAC, i) == true then
      -- the frame must be somewhere on screen, else the box is left unclipped
      local fx, fy = CHD_G(CHD.TAC, i, CHD.TOUCH_LIST)
      if not CHD.clipLogged then
        CHD_Log("clip box " .. i .. " frame at " .. tostring(fx) .. "," .. tostring(fy))
        if i == 2 then
          CHD.clipLogged = true
        end
      end
      if fx ~= nil and math.abs(fx) < 4096 and math.abs(fy) < 4096 then
        CHD_Cmd(CHD.SCISSOR_UPDATE, CHD.TAC, i)
        CHD_Cmd(CHD.SCISSOR_COPY, CHD.CMD, i, CHD.TAC, i)
        CHD_Cmd(CHD.SCISSOR_ON, CHD.CMD, i, true)
      else
        CHD_Cmd(CHD.SCISSOR_ON, CHD.CMD, i, false)
      end
    end
  end
end

CHD_G = function(layer, idx, node)
  local ok, x, y = CHD_Cmd(CHD.GPOS, layer, idx, node)
  if ok and type(x) == "number" and type(y) == "number" then
    return x, y
  end
  return nil
end

-- every Step: the kit's centre onto its place between the team name and player plates, measured in global units (the bar's and the field's
-- scales come from known node distances, so another mod scaling / moving the pitch or the bar changes nothing)
local function CHD_FixKit()
  if CHD.hdr ~= "header" or CHD_Get(CHD.IS_OPEN, CHD.BAR, 0) ~= true or CHD_Get(CHD.IS_OPEN, CHD.UNI, 0) ~= true then
    return
  end
  local bx, by = CHD_G(CHD.BAR, 0, CHD.POS_BASE)
  local ex, ey = CHD_G(CHD.BAR, 0, CHD_HDR.crest)
  local ux, uy = CHD_G(CHD.UNI, 0, CHD.POS_BASE)
  local ix, iy = CHD_G(CHD.UNI, 0, CHD.KIT_ICON)
  if bx == nil or ex == nil or ux == nil or ix == nil then
    return
  end
  local cr = CHD_BAR_CREST
  local kbx, kby = (ex - bx) / cr[1], (ey - by) / cr[2]
  local kux, kuy = (ix - ux) / CHD_UNI[1][2], (iy - uy) / CHD_UNI[1][3]
  if math.abs(kbx) < 0.05 or math.abs(kby) < 0.05 or math.abs(kux) < 0.05 or math.abs(kuy) < 0.05 then
    return
  end
  -- where the kit is drawn now (global units: centre, half sizes of its focus frame), for the pointer guard
  CHD.kitc = {ux + CHD_HDR.ux * kux, uy + CHD_HDR.uy * kuy, CHD_UNI[3][4] / 2 * math.abs(kux),
    CHD_UNI[3][5] / 2 * math.abs(kuy)}
  -- the kit's centre: midway between the measured team name plate's right edge and the player plate's left edge
  -- (where the retail «Nv. EQUIPO» sat), in bar units; the layout's value only while the plates are not measurable
  local kx = CHD_HDR.kx
  local nx = CHD_G(CHD.NAME, 0, CHD.NAME_BASE)
  local px = CHD_G(CHD.DECK, 0, CHD.DECK_BASE)
  CHD.nameR = nx ~= nil and nx + CHD_NAME[1][4] * kbx or nil   -- the drawn team name plate's right edge (global)
  if nx ~= nil and px ~= nil then
    local gl, gr = (nx - bx) / kbx + CHD_NAME[1][4], (px - bx) / kbx
    if gr > gl and gr - gl < 600 then
      kx = (gl + gr) / 2
    end
  end
  -- the kit's centre (CHD_HDR.ux / uy in its layer: the retail hit zone's centre) onto the target, so the layer
  -- origin goes there minus that offset
  local tx, ty = bx + kx * kbx - CHD_HDR.ux * kux, by + CHD_HDR.ky * kby - CHD_HDR.uy * kuy
  local dx, dy = (tx - ux) / kux, (ty - uy) / kuy
  if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    return
  end
  for _, frame in ipairs(CHD.FRAMES) do
    if CHD_Get(CHD.IS_OPEN, frame, 0) == true then
      local k = CHD_KitAtc(frame)
      if k ~= nil then
        k[1], k[2] = k[1] + dx, k[2] + dy
        CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 0, k[1])
        CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 1, k[2])
      end
    end
  end
end

-- ---- focus ---------------------------------------------------------------------------------------------------------------
local function CHD_Active(layer)
  return CHD_Get(CHD.FOCUS_ACTIVE, layer) == true
end

local function CHD_Idx(layer)
  local v = CHD_Get(CHD.FOCUS_IDX, layer)
  if type(v) == "number" then
    return v
  end
  return 0
end

local function CHD_Num(layer)
  local v = CHD_Get(CHD.CREATE_NUM, layer)
  if type(v) == "number" then
    return v
  end
  return 1
end

local function CHD_Open(layer, idx)
  return CHD_Get(CHD.IS_OPEN, layer, idx or 0) == true
end

-- every Step (one correction, then 2 Steps to let the global positions follow): the AT / DF block (its _pos_scl01,
-- the centre of its line) onto CHD_ATDF.tx / ty field units from the keeper's spot _pos_formation01, the block scaled
-- to CHD_ATDF.scale of the field's scale. Everything measured in global units, so the dock's slide-in, a dock switch
-- or another mod moving / scaling the pitch or the block's layout only changes where it lands, not that it is under
-- the keeper. Only on the 11v11 pitch; otherwise the layer goes back to its retail transform.
local function CHD_Atdf()
  local A, st = CHD_ATDF, CHD.atdf
  if CHD_Get(CHD.IS_OPEN, A.layer, 0) ~= true then
    return
  end
  if not CHD_AtdfOn() or CHD_Get(CHD.IS_OPEN, A.frame, 0) ~= true then
    if st.x ~= 0 or st.y ~= 0 or st.s ~= 1 then
      st.x, st.y, st.s = 0, 0, 1
      CHD_AtdfSend()
    end
    return
  end
  if st.wait > 0 then
    st.wait = st.wait - 1
    return
  end
  local fbx, fby = CHD_G(A.frame, 0, CHD.POS_BASE)
  local ffx, ffy = CHD_G(A.frame, 0, A.field)
  local gx, gy = CHD_G(A.frame, 0, A.gk)
  local abx = CHD_G(A.layer, 0, CHD.POS_BASE)
  local asx, asy = CHD_G(A.layer, 0, A.scl)
  local _, any = CHD_G(A.layer, 0, A.num)
  if fbx == nil or ffx == nil or gx == nil or abx == nil or asx == nil or any == nil then
    return
  end
  local kfx, kfy = (ffx - fbx) / A.fx, (ffy - fby) / A.fy        -- global units per field unit
  local kax, kay = (asx - abx) / A.dx / st.s, (any - asy) / A.dy / st.s   -- per unscaled layer unit
  if math.abs(kfx) < 0.05 or math.abs(kfy) < 0.05 or math.abs(kax) < 0.05 or math.abs(kay) < 0.05 then
    return
  end
  local s = A.scale * kfy / kay
  if s < 0.2 or s > 1.5 then
    s = A.scale
  end
  local tx, ty = gx + A.tx * kfx, gy + A.ty * kfy
  local dx, dy = (tx - asx) / kax, (ty - asy) / kay
  if math.abs(s - st.s) < 0.005 and math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    return
  end
  if math.abs(s - st.s) >= 0.005 then
    st.s = s                      -- the scale first (about the layer origin): the position is measured again after it
  else
    st.x, st.y = st.x + dx, st.y + dy
  end
  CHD_AtdfSend()
  st.wait = 2
  if st.n < 12 then
    st.n = st.n + 1
    CHD_Log(string.format("atdf -> pos %.1f, %.1f scale %.3f (block was %.1f, %.1f from target)", st.x, st.y, st.s,
      dx, dy))
  end
end

local function CHD_ConfShown()
  if not CHD_Open(CHD.CONF, 0) then
    return false
  end
  if type(IsVisibleTeamBuildTypeIcon) == "function" then
    local ok, v = pcall(IsVisibleTeamBuildTypeIcon, CHD.CONF)
    if ok and v == false then
      return false
    end
  end
  return true
end

-- the focus lands on (layer, idx): the retail marker, the engine's own index if the marker did not move it, then the
-- dock's OnChangeFocus (run by the engine's echo, else here) for its cursor / guide line / tactic info / balloon
local function CHD_SetFocus(layer, idx)
  CHD.busy, CHD.echo = true, false
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, true)
  if CHD_Idx(layer) ~= idx then
    CHD_Cmd(CHD.FOCUS_SET, layer, idx)
  end
  CHD.busy = false
  if not CHD.echo and type(OnChangeFocus) == "function" then
    pcall(OnChangeFocus, layer, idx)
  end
end

-- one instance of the tactics row to another, as the engine's own step inside a layer
local function CHD_TacStep(from, to)
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], CHD.TAC, from, 1286797620 --[[Active]], 2, 973515837 --[[button]])
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], CHD.TAC, from, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
  CHD_Cmd(CHD.CURSOR_LOC, CHD.TAC, CHD.CURSOR, to, CHD_Num(CHD.TAC))
  CHD_SetFocus(CHD.TAC, to)
end

-- the focus mark and highlight off on an instance that no longer holds the focus (what the retail OnMouseMove does
-- to the item the pointer leaves, plus the out animations of OnFocusLayerShift)
local function CHD_Unfocus(layer, idx)
  CHD.busy = true
  CHD_Cmd(CHD.FOCUS_MARK, layer, idx, false)
  CHD.busy = false
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 1286797620 --[[Active]], 2, 973515837 --[[button]])
  CHD_Cmd(3781155141 --[[CMND_PLAY_ANIME_TYPE]], layer, idx, 2734777837 --[[Focus]], 2, 973515837 --[[button]])
end

-- (from, fi) -> (to, ti) like a retail focus shift row: the dock's OnFocusLayerShift (plates, cursor trace, control
-- focus), the control focus, the cursor, the focus itself. `from` is unmarked: when it is the transient target of a
-- retail shift row this layout re-routes (FORMACIÓN DOWN -> CONF., kit LEFT -> CONF., team name RIGHT -> player
-- plate…), the engine had marked it and played its focus-in, and without this it kept its frame next to the real
-- focus (two items highlighted, in game 1.14.0). It is unmarked again for CHD_GHOST_STEPS Steps (CHD_Ghost): the
-- engine's own focus-in of the shift can land after this Step.
local CHD_GHOST_STEPS = 3
local function CHD_Go(from, fi, to, ti)
  if CHD.moves < 80 then
    CHD.moves = CHD.moves + 1
    CHD_Log("focus " .. tostring(from) .. "[" .. tostring(fi) .. "] -> " .. tostring(to) .. "[" .. tostring(ti) .. "]")
  end
  CHD.going = true
  if type(OnFocusLayerShift) == "function" then
    pcall(OnFocusLayerShift, from, fi, to, ti)
  end
  CHD.going = false
  CHD.focusAt = to
  CHD_Cmd(CHD.FOCUS_ENABLE, from, false)
  CHD_Cmd(CHD.FOCUS_ENABLE, to, true)
  CHD_Cmd(CHD.CURSOR_LOC, to, CHD.CURSOR, ti, CHD_Num(to))
  CHD_SetFocus(to, ti)
  if from ~= to then
    CHD_Unfocus(from, fi)
    CHD.ghost = {from, fi, CHD_GHOST_STEPS}
  end
end

-- every Step after a CHD_Go: the left item unmarked again while it does not hold the focus
local function CHD_Ghost()
  local g = CHD.ghost
  if g == nil then
    return
  end
  g[3] = g[3] - 1
  if g[3] <= 0 then
    CHD.ghost = nil
  end
  if not CHD_Active(g[1]) then
    CHD_Unfocus(g[1], g[2])
  else
    CHD.ghost = nil                -- the focus came back to it: leave it alone
  end
end

-- the nearest card of the pitch / bench from (layer, idx) in a retail direction (1 up, 2 down, 3 left, 4 right; the
-- retail MoveToOtherLayer / CalcMoveFocusLayerIdx: positions measured, a 37° cone) -> card index or nil
local function CHD_CardFrom(dir, layer, idx)
  if type(MoveToOtherLayer) ~= "function" then
    return nil
  end
  local ok, ci, cl = pcall(MoveToOtherLayer, dir, layer, idx, CHD.CARDS, CHD_Num(CHD.CARDS), 37, true)
  if not ok or ci == nil or ci == -1 or cl ~= CHD.CARDS then
    return nil
  end
  return ci
end

-- the focus onto pitch card `ci` the way the retail moves there from the panel (control focus, cursor, mark, the
-- dock's selected card, its guide line, no build balloon); `from` = the layer the engine / this graft left
local function CHD_ToCard(from, fi, ci)
  -- the green cursor leaves `from` for the card, as the retail OnFocusLayerShift does (else it stays on the kit)
  for i = 0, CHD_Num(from) - 1 do
    CHD_Cmd(CHD.CURSOR_TRACE, from, i, CHD.CURSOR, false)
  end
  CHD_Cmd(CHD.CURSOR_TRACE, CHD.CARDS, ci, CHD.CARD_CURSOR, true)
  CHD.focusAt = CHD.CARDS
  CHD_Cmd(CHD.FOCUS_ENABLE, from, false)
  CHD_Cmd(CHD.FOCUS_ENABLE, CHD.CARDS, true)
  CHD_Cmd(CHD.CURSOR_LOC, CHD.CARDS, CHD.CURSOR, ci, CHD_Num(CHD.CARDS))
  if type(SetIsTeamDockTop) == "function" then
    pcall(SetIsTeamDockTop, false)
  end
  if type(UpdateChangeFocusLayer) == "function" then
    pcall(UpdateChangeFocusLayer, CHD.CARDS, ci, ci, CHD.CARDS)
  end
  if type(SetSelectCharaIdx) == "function" then
    pcall(SetSelectCharaIdx, ci)
  end
  local text = CHD_Lc(CHD.TEXT_GET, CHD.CARD_GUIDE)
  if type(text) == "string" then
    CHD_Cmd(CHD.SET_TEXT, CHD.GUIDE_LINE, CHD.GUIDE_NODE, text, 0)
  end
  CHD_Cmd(CHD.LAYER_VISIBLE, CHD.BALLOON, 0, false)
  if from ~= CHD.CARDS then
    CHD_Unfocus(from, fi)
    CHD.ghost = {from, fi, CHD_GHOST_STEPS}
  end
end

-- header mode, FORMACIÓN DOWN: the panel has no row below FORMACIÓN | CONF. (the kit is in the header), so the next
-- row down is the nearest card below it (retail measure, as the tactics' UP to the coach card); none -> FORMACIÓN
-- keeps the focus. `at` / `ai` = where the engine's retail row put the focus (CONF. after the shift), unmarked
local function CHD_FormDown(at, ai)
  local ci = CHD_CardFrom(2, CHD.FORM, 0)
  if ci ~= nil then
    if CHD.moves < 80 then
      CHD.moves = CHD.moves + 1
      CHD_Log("focus " .. tostring(at) .. "[" .. tostring(ai) .. "] -> card " .. tostring(ci) .. " (FORMACIÓN DOWN)")
    end
    CHD_ToCard(at, ai, ci)
    if at ~= CHD.FORM then
      CHD_Unfocus(CHD.FORM, 0)
    end
  elseif at ~= CHD.FORM then
    CHD_Go(at, ai, CHD.FORM, 0)
  end
end

-- CONF. DE EQUIPO -> the pitch on the right: the retail EQUIPACIÓN move (OnChangeFocus, right) from the CONF. box
local function CHD_ConfToPitch(at, ai)
  at, ai = at or CHD.CONF, ai or 0
  local ci = CHD_CardFrom(4, CHD.CONF, 0)
  if ci ~= nil then
    CHD_ToCard(at, ai, ci)
    if at ~= CHD.CONF then
      CHD_Unfocus(CHD.CONF, 0)
    end
  elseif at ~= CHD.CONF then
    CHD_Go(at, ai, CHD.CONF, 0)   -- no card on the right: CONF. keeps the focus
  end
end

-- ---- another mod's picture button (BetterUI.AddDockButton) ---------------------------------------------------------------
CHD.SYN_UPPER, CHD.SYN_LOWER = 830633104, 1179455358   -- team00_17_synergy_attachment_button_flag / _pillar
CHD.slot = {layer = nil, x = 0, y = 0, wait = 0, placed = false, n = 0, extra = {}, live = 0, still = 0}
local CHD_SLOT_STILL = 8          -- Steps the button must stay on its place (the dock's slide-in over) before placing stops

-- the button shown: the first registered one whose layer is open (nil = none; never in the one-row tactics layout)
local function CHD_SlotLayer()
  if CHD_TacOn() then
    return nil
  end
  local bu = rawget(_ENV, "BetterUI")
  local list = type(bu) == "table" and rawget(bu, "DockButtons") or nil
  if type(list) ~= "table" then
    return nil
  end
  for _, e in ipairs(list) do
    if type(e) == "table" and type(e.layer) == "number" and CHD_Open(e.layer, 0) then
      return e.layer, e
    end
  end
  return nil
end

-- the button's help line in the dock's guide line
local function CHD_SlotHelp(spec)
  if type(spec) == "table" and type(spec.help) == "number" then
    local text = CHD_Lc(CHD.TEXT_GET, spec.help)
    if type(text) == "string" then
      CHD_Cmd(CHD.SET_TEXT, CHD.GUIDE_LINE, CHD.GUIDE_NODE, text, 0)
    end
  end
end

-- (from, fi) -> the button, with its help line
local function CHD_ToSlot(from, fi)
  local layer, spec = CHD_SlotLayer()
  if layer == nil or not CHD.slot.placed then
    return false
  end
  CHD_Go(from, fi, layer, 0)
  CHD_SlotHelp(spec)
  return true
end

-- the spec's `extra` layers (root layers drawn over the button, e.g. its picture): their origin onto the button's,
-- measured in global units against the button (same layout units), hidden until there
local function CHD_SlotExtra(spec, bx, by, kbx, kby)
  local st = CHD.slot
  for _, ex in ipairs(type(spec) == "table" and type(spec.extra) == "table" and spec.extra or {}) do
    -- (an extra layer need not report itself open: the stadium picture frame never did, 1.22.13; it is placed as soon
    -- as its origin can be measured)
    if type(ex) == "number" and CHD_G(ex, 0, CHD.POS_BASE) ~= nil then
      local e = st.extra[ex]
      if e == nil then
        e = {x = 0, y = 0, wait = 0, placed = false}
        st.extra[ex] = e
        CHD_Cmd(CHD.LAYER_VISIBLE, ex, 0, false)
      end
      if e.wait > 0 then
        e.wait = e.wait - 1
      else
        local ex_x, ex_y = CHD_G(ex, 0, CHD.POS_BASE)
        if ex_x ~= nil then
          local dx, dy = (bx - ex_x) / kbx, (by - ex_y) / kby
          if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
            if not e.placed then
              e.placed = true
              CHD_Cmd(CHD.LAYER_VISIBLE, ex, 0, true)
              CHD_Log("dock button " .. tostring(st.layer) .. ": layer " .. tostring(ex) .. " placed on it")
            end
          else
            e.x, e.y = e.x + dx, e.y + dy
            CHD_Cmd(CHD.LAYER_POS, ex, e.x, e.y, 0, 0)
            e.wait = 2
          end
        end
      end
    end
  end
end

-- (re)start placing the button: the events that move it (its layer / the field opening, the team switch, the dock back
-- from a child menu); placing runs until it has stayed on its place CHD_SLOT_STILL Steps
local function CHD_SlotArm()
  local st = CHD.slot
  st.live, st.still = 1, 0
  if CHD.row ~= nil then
    CHD.row.live, CHD.row.still = 1, 0
  end
  for _, e in pairs(st.extra or {}) do
    e.wait = 0
  end
end
CHD.SlotArm = CHD_SlotArm

local function CHD_SlotPlace()
  local layer, spec = CHD_SlotLayer()
  local st = CHD.slot
  if layer == nil then
    return
  end
  if st.layer ~= layer then
    st.layer, st.x, st.y, st.wait, st.placed, st.n, st.extra, st.live, st.still = layer, 0, 0, 0, false, 0, {}, 1, 0
    CHD_Cmd(CHD.LAYER_VISIBLE, layer, 0, false)
  end
  -- the spec's own tick (its selector while it is open): every Step of the dock while the button's layer is open
  if type(spec.step) == "function" then
    local ok, err = pcall(spec.step, st.placed)
    if not ok and not st.stepErr then
      st.stepErr = true
      CHD_Log("dock button " .. tostring(layer) .. " step error " .. tostring(err))
    end
  end
  if st.live <= 0 then
    return                        -- placed and still: nothing until an event arms it again (CHD_SlotArm)
  end
  if st.wait > 0 then
    st.wait = st.wait - 1
    return
  end
  if st.placed and st.kb ~= nil then
    local bx0, by0 = CHD_G(layer, 0, CHD.POS_BASE)
    if bx0 ~= nil then
      CHD_SlotExtra(spec, bx0, by0, st.kb[1], st.kb[2])
    end
  end
  local ux, uy = CHD_G(CHD.SYN_UPPER, 0, CHD.POS_BASE)
  local lx, ly = CHD_G(CHD.SYN_LOWER, 0, CHD.POS_BASE)
  -- the spec's scale reference (a mesh node and its layout translation, default the synergy plate) and the point of
  -- its layer that goes on the slot's centre (layer units, default the origin), in the synergy buttons' column or on
  -- the panel's centre (column = "panel")
  local ms = type(spec.mesh) == "table" and spec.mesh or {node = CHD_SLOT.mesh, x = CHD_SLOT.mx, y = CHD_SLOT.my}
  local ce = type(spec.center) == "table" and spec.center or {x = 0, y = 0}
  local bx, by = CHD_G(layer, 0, CHD.POS_BASE)
  local mx, my = CHD_G(layer, 0, ms.node)
  if ux == nil or lx == nil or bx == nil or mx == nil then
    return
  end
  local k = (ly - uy) / CHD_SLOT.step                     -- global units per field unit (y, signed)
  local kbx, kby = (mx - bx) / ms.x, (my - by) / ms.y     -- per button layer unit
  if math.abs(k) < 0.05 or math.abs(kbx) < 0.05 or math.abs(kby) < 0.05 then
    return
  end
  st.kb = {kbx, kby}
  local col = spec.column == "panel" and CHD_SLOT.pdx or CHD_SLOT.dx
  local tx, ty = lx + col * math.abs(k), ly + CHD_SLOT.dy * k
  local dx, dy = (tx - (bx + ce.x * kbx)) / kbx, (ty - (by + ce.y * kby)) / kby
  if math.abs(dx) < 0.5 and math.abs(dy) < 0.5 then
    if not st.placed then
      st.placed = true
      CHD_Cmd(CHD.LAYER_VISIBLE, layer, 0, true)
      CHD_Log(string.format("dock button %s placed at %.1f, %.1f", tostring(layer), st.x, st.y))
    end
    st.still = st.still + 1
    if st.still >= CHD_SLOT_STILL then
      st.live = 0                 -- the slide-in is over: placing stops until the next event
    end
    return
  end
  st.still = 0
  st.x, st.y = st.x + dx, st.y + dy
  CHD_Cmd(CHD.LAYER_POS, layer, st.x, st.y, 0, 0)
  st.wait = 2
  if st.n < 8 then
    st.n = st.n + 1
    CHD_Log(string.format("dock button %s -> pos %.1f, %.1f (was %.1f, %.1f from its place)", tostring(layer), st.x, st.y,
      dx, dy))
  end
end

