-- CMD_FCS_MTX_* (CONF. DE EQUIPO up / down / right, EQUIPACIÓN left): (layer, dx, dy) with dx > 0 right, dy < 0 up
local chd_prev_mtx = rawget(_ENV, "MoveFocusMtx")
