  end
end)

-- keys without a retail input row on that layer: CONF. LEFT, EQUIPACIÓN DOWN. Read while the layer holds the focus and
-- no child menu is up
local function CHD_Key(cmd)
  return CHD_Lc(CHD.CHECK_INPUT, CHD.MENU_CTRL, cmd) == true or CHD_Lc(CHD.CHECK_INPUT, CHD.MENU_CTRL_ANALOG, cmd) == true
end

local function CHD_Free(layer)
  if not CHD_Active(layer) or CHD_Get(CHD.LAYER_ACTIVE, layer) == false then
    return false
  end
  for _, m in ipairs(CHD.CHILDREN) do
    if CHD_Get(CHD.EXIST_MENU, m) == true then
      return false
    end
  end
  return true
end

local function CHD_Poll()
  if CHD_Free(CHD.CONF) and CHD_Key(CHD.CMD_LEFT) then
    CHD_Go(CHD.CONF, 0, CHD.FORM, 0)
    CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
  elseif CHD.hdr == "header" and CHD_Free(CHD.UNI) and CHD_Key(CHD.CMD_DOWN) and CHD_Open(CHD.TAC, 0) then
    CHD_Go(CHD.UNI, 0, CHD.TAC, 0)
    CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
  end
end

-- another mod's picture button: its own input rows send UP / DOWN / RIGHT as CMD_FUNCTION with these arguments (the
-- button's mod declares the rows; BetterUI.AddDockButton) -> the dock's OnFunction(arg): UP TÁCTICAS (bottom row),
-- DOWN FORMACIÓN, RIGHT the nearest card. ENTER is the mod's own (its OnEnter)
CHD.FN = {UP = 2122449173, DOWN = 885050662, RIGHT = 3622053520}   -- betterui_dock_button_up / _down / _right
local chd_prev_fn = rawget(_ENV, "OnFunction")
if type(chd_prev_fn) == "function" then
  rawset(_ENV, "OnFunction", function(a1, ...)
    local RF = CHD.ROW.FN
    if a1 == RF.LEFT or a1 == RF.RIGHT or a1 == RF.UP or a1 == RF.DOWN then
      local L = CHD.ROW.LAYER
      if CHD_RowOn() and CHD_Active(L) then
        local i = CHD_Idx(L)
        if a1 == RF.LEFT and i > 0 then
          CHD_Go(L, i, L, i - 1)
          CHD.row.last = i - 1
          CHD_RowHelp(i - 1)
          CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
        elseif a1 == RF.RIGHT and i < #CHD.ROW.KINDS - 1 then
          CHD_Go(L, i, L, i + 1)
          CHD.row.last = i + 1
          CHD_RowHelp(i + 1)
          CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
        elseif a1 == RF.RIGHT then
          local ci = CHD_CardFrom(4, L, i)
          if ci ~= nil then
            CHD_ToCard(L, i, ci)
            CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
          end
        elseif a1 == RF.UP and CHD_Open(CHD.TAC, 0) then
          CHD_Go(L, i, CHD.TAC, 0)
          CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
        elseif a1 == RF.DOWN then
          if CHD_ToSlot(L, i) then
            CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
          elseif CHD_Open(CHD.FORM, 0) then
            CHD_Go(L, i, CHD.FORM, 0)
            CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
          end
        end
      end
      return
    end
    if a1 == CHD.FN.UP or a1 == CHD.FN.DOWN or a1 == CHD.FN.RIGHT then
      local slot = CHD_SlotLayer()
      if slot ~= nil and CHD_Active(slot) then
        if a1 == CHD.FN.UP and CHD_ToRow(slot, 0) then
          CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
        elseif a1 == CHD.FN.UP and CHD_Open(CHD.TAC, 0) then
          CHD_Go(slot, 0, CHD.TAC, 0)
          CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
        elseif a1 == CHD.FN.DOWN and CHD_Open(CHD.FORM, 0) then
          CHD_Go(slot, 0, CHD.FORM, 0)
          CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
        elseif a1 == CHD.FN.RIGHT then
          local ci = CHD_CardFrom(4, slot, 0)
          if ci ~= nil then
            CHD_ToCard(slot, 0, ci)
            CHD_Lc(CHD.SOUND, CHD.SE_MOVE)
          end
        end
      end
      return
    end
    return chd_prev_fn(a1, ...)
  end)
end

-- ENTER on a shortcut tile (its input row): the tile's list row, decided by the dock itself (CHD_RowDecide)
local chd_prev_enter = rawget(_ENV, "OnEnter")
if type(chd_prev_enter) == "function" then
  rawset(_ENV, "OnEnter", function(a1, a2, ...)
    if a1 == CHD.ROW.LAYER and CHD_RowOn() then
      CHD_RowDecide(type(a2) == "number" and a2 or CHD_Idx(a1))
      return
    end
    return chd_prev_enter(a1, a2, ...)
  end)
end

-- ---- header mode: decided once the bar's layers are open, then the placed header is measured ----------------------
local function CHD_SetMode(mode, why)
  CHD.hdr = mode
  CHD_Log("header " .. mode .. " (" .. why .. ")")
  for _, L in ipairs({CHD.BAR, CHD.NAME, CHD.UNI}) do
    if CHD_Open(L, 0) then
      CHD_ApplyHeader(L, mode)
    end
  end
  for _, frame in ipairs(CHD.FRAMES) do
    if CHD_Open(frame, 0) then
      local k = mode == "header" and CHD_KitAtc(frame) or CHD_UNI_PANEL[frame]
      CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 0, k[1])
      CHD_Cmd(CHD.NODE_POS, frame, 0, CHD.ATC_UNI, 1, k[2])
    end
  end
end

-- a plate is there once its layer is open and not hidden. The bar opens the kit and the plates in one OnOpenLayer,
-- but the plates (fonts) finish loading / become visible a few Steps after the kit: in game (1.6.0) the first Step
-- with the bar and the kit open still saw no team name plate on every dock, so a missing plate only counts once it
-- is still missing after CHD_PLATE_WAIT Steps
local CHD_PLATE_WAIT = 120
local function CHD_Plate(layer)
  local open = CHD_Open(layer, 0)
  local vis = open and CHD_Get(CHD.IS_VISIBLE, layer, 0) ~= false
  return open and vis, open
end

local function CHD_Decide()
  if CHD.hdr ~= nil or not CHD_Open(CHD.BAR, 0) or not CHD_Open(CHD.UNI, 0) then
    return
  end
  if rawget(_ENV, "g_parentMenuId") == CHD.VR_MENU then
    CHD_SetMode("panel", "opened from the Victory Road")
    return
  end
  local name, nameOpen = CHD_Plate(CHD.NAME)
  local deck, deckOpen = CHD_Plate(CHD.DECK)
  if name and deck then
    CHD_SetMode("header", "crest | team name | kit | player plate | Nv., after " .. CHD.wait .. " Step(s)")
    CHD.check = 30
    return
  end
  CHD.wait = CHD.wait + 1
  if CHD.wait < CHD_PLATE_WAIT then
    return                        -- not decided yet: the header stays retail meanwhile
  end
  if not name then
    CHD_SetMode("panel", "no team name plate after " .. CHD.wait .. " Steps (open " .. tostring(nameOpen) .. ")")
  else
    CHD_SetMode("panel", "no player plate after " .. CHD.wait .. " Steps (open " .. tostring(deckOpen) .. ")")
  end
end

-- the placed team name and player plates where this layout put them (global units, the bar's measured scale), logged
-- once 30 Steps after the header mode is set. Log only: the 1.6.0 guard fell back to the retail header when they
-- were off, but the plates are attached layers whose global positions lag the bar's by a frame, so the Step after
-- the relayout measured them exactly at their retail places (-542 / 176) on every dock (in game 2026-10-03 12:21)
local function CHD_Check()
  if CHD.check <= 0 or CHD.hdr ~= "header" then
    return
  end
  CHD.check = CHD.check - 1
  if CHD.check > 0 then
    return
  end
  local bx, by = CHD_G(CHD.BAR, 0, CHD.POS_BASE)
  local ex = CHD_G(CHD.BAR, 0, CHD_HDR.crest)
  local nx = CHD_G(CHD.NAME, 0, CHD.NAME_BASE)
  local dx = CHD_G(CHD.DECK, 0, CHD.DECK_BASE)
  if bx == nil or ex == nil or nx == nil or dx == nil then
    return                        -- not measurable: kept
  end
  local k = (ex - bx) / CHD_BAR_CREST[1]
  if math.abs(k) < 0.05 then
    return
  end
  local en, ed = (nx - bx) / k, (dx - bx) / k
  CHD_Log(string.format("header measured: team name %.0f / player plate %.0f (layout %.0f / %.0f)",
    en, ed, CHD_HDR_CHECK.name_l, CHD_HDR_CHECK.deck_l))
end

-- the retail focus SHIFT rows (setting) this layout re-routes: the engine moved the focus from -> to by itself;
-- the focus goes on to this layout's target (only if it is still where the engine put it): at once for a key shift,
-- else on the next Step (see the OnFocusLayerShift wrapper below)
local function CHD_Redirect(sh, key)
  local f, fi, t, ti = sh[1], sh[2], sh[3], sh[4]
  if not CHD_Active(t) then
    return
  end
  -- TÁCTICAS DOWN (a key): the shortcut row under the tactics
  if key and f == CHD.TAC and t == CHD.FORM and CHD_ToRow(t, ti) then
    return
  end
  -- TÁCTICAS DOWN / FORMACIÓN UP (a key, not the pointer): another mod's picture button between them
  if key and ((f == CHD.TAC and t == CHD.FORM) or (f == CHD.FORM and t == CHD.TAC)) and CHD_ToSlot(t, ti) then
    return
  end
  local hdr = CHD.hdr == "header"
  if hdr and f == CHD.NAME and t == CHD.DECK and CHD_Open(CHD.UNI, 0) then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- team name RIGHT -> kit
  elseif hdr and f == CHD.DECK and t == CHD.NAME and CHD_Open(CHD.UNI, 0) then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- player plate LEFT -> kit
  elseif hdr and f == CHD.UNI and t == CHD.FORM then
    CHD_Go(t, ti, CHD.UNI, 0)                 -- kit UP: nothing above it in the header
  elseif hdr and f == CHD.UNI and t == CHD.CONF and CHD_Open(CHD.NAME, 0) then
    CHD_Go(t, ti, CHD.NAME, 0)                -- kit LEFT -> team name
  elseif f == CHD.FORM and t == CHD.TAC and CHD_TacOn() and CHD_Open(CHD.TAC, 2) then
    CHD_Go(t, ti, CHD.TAC, 2)                 -- FORMACIÓN UP -> left tactic box
  elseif f == CHD.FORM and t == CHD.CONF then
    if hdr then
      CHD_FormDown(t, ti)                     -- FORMACIÓN DOWN: the card below, else FORMACIÓN stays
    elseif CHD_Open(CHD.UNI, 0) then
      CHD_Go(t, ti, CHD.UNI, 0)               -- panel mode: the kit under the panel
    end
  elseif f == CHD.CONF and t == CHD.FORM and CHD_Open(CHD.TAC, 0) then
    CHD_Go(t, ti, CHD.TAC, 0)                 -- CONF. UP -> right tactic box
  elseif f == CHD.CONF and t == CHD.UNI then
    CHD_ConfToPitch(t, ti)                    -- CONF. RIGHT -> the pitch
  elseif f == CHD.TAC and t == CHD.FORM and fi == 0 and CHD_TacOn() and CHD_ConfShown() then
    CHD_Go(t, ti, CHD.CONF, 0)                -- right tactic box DOWN -> CONF.
  end
end

-- a D-pad / arrow / stick step this frame (the input a key shift row answers)
local function CHD_NavKey()
  return CHD_Key(CHD.CMD_DOWN) or CHD_Key(CHD.CMD_UP) or CHD_Key(CHD.CMD_LEFT) or CHD_Key(CHD.CMD_RIGHT)
end

-- 2026-10-13 (owner video: FORMACIÓN DOWN lit CONF. DE EQUIPO for one frame, then FORMACIÓN again). The key shift row
-- (nie 0x10DC7B0) moves the control focus, the mark / focus-in and the sound to its target and calls this callback as
-- its LAST step (vtable 0x168 -> 0x10C9710), then the input is done; the Step runs before the input in a frame, so a
-- redirect on the next Step let the retail target render for one frame. A key shift is now redirected here, before
-- that frame is drawn. The pointer's group switch (0x535F80, OnMouseMove) also calls this callback but sets its focus
-- AFTER it, so a shift without a D-pad / arrow / stick step this frame keeps the next-Step redirect.
local chd_prev_shift = rawget(_ENV, "OnFocusLayerShift")
if type(chd_prev_shift) == "function" then
  rawset(_ENV, "OnFocusLayerShift", function(a1, a2, a3, a4, ...)
    local r = CHD_Pack(chd_prev_shift(a1, a2, a3, a4, ...))
    CHD.focusAt = a3              -- where the focus went (any shift: a key, the pointer, CHD_Go)
    if not CHD.going and CHD_PanelOn() then
      local sh = {a1, a2, a3, a4}
      local now = not CHD.busy and CHD_NavKey()
      if CHD.moves < 80 then
        CHD.moves = CHD.moves + 1
        CHD_Log("shift " .. tostring(a1) .. "[" .. tostring(a2) .. "] -> " .. tostring(a3) .. "[" .. tostring(a4) .. "]"
          .. (now and " (key: redirected now)" or " (redirect on the next Step)"))
      end
      if now then
        CHD.shift = nil
        local ok, err = pcall(CHD_Redirect, sh, true)
        if not ok then
          CHD_Log("error shift redirect " .. tostring(err))
        end
      elseif a3 == CHD.ROW.LAYER then
        CHD.shift = nil           -- onto a shortcut tile (the pointer): kept, with its help line
        CHD_RowHelp(a4 or 0)
      elseif a3 == CHD_SlotLayer() then
        CHD.shift = nil           -- onto another mod's picture button (the pointer): kept, with its help line
        CHD_SlotHelp(select(2, CHD_SlotLayer()))
      elseif (a1 == CHD.FORM or a1 == CHD.CONF) and (a3 == CHD.FORM or a3 == CHD.CONF) and CHD.PointerOnBox(a3) then
        CHD.shift = nil           -- the pointer's group switch onto the box under it: not a key move, kept as it is
      else
        CHD.shift = sh
      end
    end
    return table.unpack(r, 1, r.n)
  end)
end

CHD_After("Step", function()
  if CHD_PanelOn() and not CHD.busy then
    CHD_Decide()
    CHD_Check()
    if CHD.shift ~= nil then
      local sh = CHD.shift
      CHD.shift = nil
      CHD_Redirect(sh)
    end
    CHD_Poll()
    if CHD_ClipOn() then
      CHD_Clip()
    end
    CHD_FixKit()
    CHD.BoxGuard()
    CHD.HeaderFocusLog()
  end
  if not CHD.busy then
    CHD.HeaderZones()
  end
  if not CHD.busy then
    CHD_Atdf()
  end
  if not CHD.busy then
    CHD_SlotPlace()
    CHD_RowPlace()
  end
  if not CHD.busy then
    CHD_Ghost()
  end
end)
